-- Oracle NetSuite -> canonical PAYMENT (NETSUITE). Generated by tools/build_silver_sql.py.
SELECT 'NETSUITE' AS SOURCE_SLOT, 'Oracle NetSuite' AS SOURCE_SYSTEM, 'NETSUITE' AS COMPANY_CODE, b.TRANID AS INVOICE_ID, p.ENTITY::STRING AS SUPPLIER_ID, b.TRANDATE AS INVOICE_DATE,
  DATEADD(day, 30, b.TRANDATE) AS DUE_DATE, p.TRANDATE AS PAYMENT_DATE, p.FOREIGNTOTAL AS AMOUNT, 0::FLOAT AS DISCOUNT_TAKEN, p.CURRENCY,
  'Net 30' AS PAYMENT_TERMS FROM {{ source('src_netsuite', 'transaction') }} p JOIN {{ source('src_netsuite', 'transaction') }} b ON b.ID = p.CREATEDFROM WHERE p.TYPE = 'VendPymt'
